            for(String action:List.of("MOVE","WRITE_OFF","RESTORE")){long requestId=action.equals("MOVE")?103:action.equals("WRITE_OFF")?104:105;jdbc.update("INSERT INTO book_copy_action_request(id,idempotency_key,operator_id,request_hash,preview_digest,schema_version,action_type,request_json,preview_json,state,expires_at,committed_at,receipt_json) VALUES (?,?,101,?,?,1,?,'{\"old\":null}','{\"old\":0}','COMMITTED','2020-01-02','2020-01-01','{\"old\":false}')",requestId,("old-history-"+action).getBytes(java.nio.charset.StandardCharsets.UTF_8),"a".repeat(64),"b".repeat(64),action);Long flow=action.equals("MOVE")?null:requestId;if(flow!=null)jdbc.update("INSERT INTO stock_flow(id,book_id,flow_type,quantity,operator_id) VALUES (?,101,?,1,101)",flow,"COPY_"+action);long beforeVersion=requestId-102;jdbc.update("INSERT INTO book_copy_action(id,request_id,ordinal,copy_id,book_id,barcode_snapshot,action_type,before_status,after_status,before_location,after_location,before_version,after_version,delta_total,delta_available,reason,operator_id,occurred_at,stock_flow_id,restores_action_id) VALUES (?,?,1,101,101,'000零Aa ',?,'AVAILABLE',?,NULL,NULL,?,?,?,0,'历史原值',101,'2020-01-01',?,?)",requestId,requestId,action,action.equals("WRITE_OFF")?"WRITTEN_OFF":action.equals("RESTORE")?"DISABLED":"AVAILABLE",beforeVersion,beforeVersion+1,action.equals("WRITE_OFF")?-1:action.equals("RESTORE")?1:0,flow,action.equals("RESTORE")?104L:null);}
